      "id": 14,
      "categoryId": "cat-hierarchical",
      "categoryName": "Hierarchical & Network Topologies",
      "title": "Graph Data Structures & Representation Models",
      "subtitle": "Vertices, Edges, Adjacency Matrix vs Adjacency List & DAG Properties",
